mapper.insert:
insert into ai_chat_session (
    student_id, student_code, title, status, message_count, last_message_at, summary,
    summary_token_count, compressed_until_message_id, archive_status, archive_id,
    expire_at, created_at, updated_at
) values (
    #{studentId}, #{studentCode}, #{title}, #{status}, #{messageCount}, #{lastMessageAt}, #{summary},
    #{summaryTokenCount}, #{compressedUntilMessageId}, #{archiveStatus}, #{archiveId},
    #{expireAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select 
from ai_chat_session
where id = #{id}
  and student_id = #{studentId}
  and status != 'DELETED'

mapper.update:
update ai_chat_session
set title = #{title},
    updated_at = #{updatedAt}
where id = #{id}
  and student_id = #{studentId}
  and (title is null or title = '' or title = '新对话')

update ai_chat_session
set message_count = (
        select count(1)
        from ai_chat_message
        where session_id = #{id}
          and student_id = #{studentId}
    ),
    last_message_at = #{lastMessageAt},
    updated_at = #{updatedAt}
where id = #{id}
  and student_id = #{studentId}

update ai_chat_session
set summary = #{summary},
    summary_token_count = #{summaryTokenCount},
    compressed_until_message_id = #{compressedUntilMessageId},
    updated_at = #{updatedAt}
where id = #{id}
  and student_id = #{studentId}

update ai_chat_session
set status = 'DELETED',
    updated_at = #{updatedAt}
where id = #{id}
  and student_id = #{studentId}
